type IssuePage = { items: Issue[]; next_page: number | null };
const repo = 'acme/web';
const targets = new Map<number, string>();
const visited = new Set<number>();
let page: number | null = 1;
while (page != null) {
  if (visited.has(page)) throw new Error('Repeated issue page');
  visited.add(page);
  const result = await tools.list_issues({ repo, state: 'open', label: 'perf', page }) as IssuePage;
  for (const issue of result.items) {
    const login = issue.assignee?.login;
    if (login && issue.state === 'open' && issue.labels.some(label => label.name === 'perf')) {
      targets.set(issue.number, login);
    }
  }
  page = result.next_page;
}
const failures: { number: number; login: string; error: string }[] = [];
let posted = 0;
for (const [number, login] of targets) {
  try {
    await tools.post_comment({ repo, number, body: `ping @${login}` });
    posted++;
  } catch (error) {
    failures.push({ number, login, error: String(error) });
  }
}
return { eligible: targets.size, posted, failures };","answer":""}

